def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = sum(1 for x in op if x == 'D')

    # If opponent is defecting frequently and just defected, defect back.
    if n > 0 and op[-1] == 'D' and opp_def / n > 0.3:
        return 'D'

    # Check if opponent retaliated to any of our defections.
    retaliated = False
    for i in range(n - 1):
        if me[i] == 'D' and op[i + 1] == 'D':
            retaliated = True
            break

    if retaliated:
        if n == 99:
            return 'D'
        return 'C'

    # No retaliation detected: cooperative/exploit phase.
    if n < 5:
        return 'C'
    if n == 5:
        if opp_def == 0:
            return 'D'
        return 'C'
    if n == 6:
        return 'C'

    if n == 99:
        return 'D'

    # Exploit mode: defect if opponent cooperated last, cooperate if they defected.
    if op[-1] == 'C':
        return 'D'
    else:
        return 'C'
